    regression_wave_regression_wave_regression_wave_regression_wave_cutoffs: Any,
) -> tuple[int, ...]:
    """Validate the deepest regression wave cutoff tuple's types.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests`,
