    :class:`int` values (a ``bool`` or non-:class:`int` element
    raises :class:`TypeError`); a negative, duplicate or
    non-strictly-increasing element raises :class:`ValueError`.
    Range against the actual deepest regression wave count is the
    caller's concern, since the wave set is only known after the
    frozen view is captured.
    """
    if not isinstance(
        regression_wave_regression_wave_regression_wave_regression_wave_cutoffs, tuple
    ):
        raise TypeError(
            f"regression_wave_regression_wave_regression_wave_regression_wave_cutoffs "
            f"must be a tuple, got "
            f"{type(regression_wave_regression_wave_regression_wave_regression_wave_cutoffs).__name__}"
        )
    validated: list[int] = []
    previous: int | None = None
    for (
        position,
